/// <summary>
/// Extension of <c>SalesPickingListJournalPost</c>
/// </summary>
[ExtensionOf(classstr(SalesPickingListJournalPost))]
public final class METSalesPickingListJournalPost_Extension
{

}

Method.Source:
    /// <summary>
    /// Updates the source line for the current journal line.
    /// </summary>
    protected void updateSourceLine()
    {
        METOrderExtractStatus       metOrderExtractStatus = METOrderExtractStatus::Open;
        WMSOrderTrans              metWMSOrderTrans;

        next updateSourceLine();

        // CB453_BackOrders
        // METAllowBackOrders only exist in SO header now
        SalesTable salesTable = salesLine.SalesTable();
        //if (salesLine && !salesLine.METAllowBackOrders)
        if (salesLine && !salesTable.METAllowBackOrders)
        {
            metOrderExtractStatus = METOrderExtractStatus::Extracted;

            SalesUpdateRemain      metSalesUpdateRemain = SalesUpdateRemain::construct();
            metSalesUpdateRemain.updateDeliverRemainder(salesLine,
                                                        EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(
                                                        salesLine.ItemId,
                                                        salesLine.InventDimId,
                                                        wmsOrderTrans.Qty,
                                                        wmsOrderTrans.UnitId(),
                                                        salesLine.SalesUnit,
                                                        NoYes::Yes),
                                                        wmsOrderTrans.Qty, 
                                                        wmsOrderTrans.pdsCWQty);
        }
        
        select sum(qty) from metWMSOrderTrans where metWMSOrderTrans.inventTransId == salesLine.InventTransId;

        // CB453_BackOrders
        // METAllowBackOrders only exist in SO header now
        //if (salesLine.METAllowBackOrders  &&
        if (salesTable.METAllowBackOrders  &&
            (salesLine.QtyOrdered == metWMSOrderTrans.qty))
        {
            metOrderExtractStatus = METOrderExtractStatus::Extracted;
        }
        // CB453_BackOrders
        // METAllowBackOrders only exist in SO header now
        //else if(salesLine.METAllowBackOrders  &&
        else if(salesTable.METAllowBackOrders  &&
            (salesLine.QtyOrdered != metWMSOrderTrans.qty))
        {
            metOrderExtractStatus = METOrderExtractStatus::Open;
        }

        METSalesLine metSalesLineOrderLine = METSalesLine::find(salesLine.RecId, true);
        if (metSalesLineOrderLine)
        {
            metSalesLineOrderLine.OrderExtractStatus = metOrderExtractStatus;
            metSalesLineOrderLine.doUpdate();
        }
        this.metUpdateOrigSalesOrder();


    }

/// <summary>
/// Update intercompany salesorder
/// </summary>
private void metUpdateOrigSalesOrder()
{
    if (salesLine.isDerivedIntercompanyLine() && salesLine.InterCompanyInventTransId)
    {
        changecompany(salesLine.salesTable().InterCompanyCompanyId)
        {
            PurchLine metPurchLine = PurchLine::findInventTransId(salesLine.InterCompanyInventTransId);
            if (metPurchLine.InterCompanyInventTransId
                    && metPurchLine.ItemRefType == InventRefType::Sales
                    && metPurchLine.InventRefTransId)
            {
                SalesLine metOrigICSalesLine = SalesLine::findInventTransId(metPurchLine.InventRefTransId);
                METSalesLine metICSalesLine = METSalesLine::find(metOrigICSalesLine.RecId, true);
                if (metICSalesLine)
                {
                    metICSalesLine.OrderExtractStatus = METOrderExtractStatus::Extracted;
                    metICSalesLine.doUpdate();
                }
                
                metOrigICSalesLine.salesTable(true).metUpdateExtractStatus();
            }
        }
    }
}

    /// <summary>
    /// Logic to execute at the end of posting.
    /// </summary>
    protected void endPost()
    {
        next endPost();

        salesTable.metUpdateExtractStatus();
    }
